using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearch.SearchAsync(query),
        nameof(WebSearch.SearchAsync),
        "Search the web for information on a topic. Returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("The title or key for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            notepad.Save(title, content);
            return $"Note saved: {title}";
        },
        "SaveNote",
        "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => notepad.GetAll(),
        "GetNotes",
        "Retrieve all saved research notes."),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Save key findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes and produce
           a well-structured summary with key points and source URLs.
        Be thorough — perform at least 2-3 searches with different query angles.
        """,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and summarizing findings.",
    tools: tools);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine(response.Text);

// --- Supporting types ---

/// <summary>Simulated web search that fetches real results via DuckDuckGo Instant Answer API.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var html = await Http.SendAsync(request);
            var body = await html.Content.ReadAsStringAsync();

            var results = ParseResults(body, maxResults: 5);
            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}\n");
            foreach (var (title, snippet, link) in results)
            {
                sb.AppendLine($"• {title}");
                sb.AppendLine($"  {snippet}");
                sb.AppendLine($"  URL: {link}");
                sb.AppendLine();
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ParseResults(
        string html, int maxResults)
    {
        var results = new List<(string, string, string)>();

        var searchIndex = 0;
        while (results.Count < maxResults)
        {
            var linkStart = html.IndexOf("class=\"result__a\"", searchIndex, StringComparison.Ordinal);
            if (linkStart < 0) break;

            var hrefPos = html.LastIndexOf("href=\"", linkStart, Math.Min(linkStart, 200), StringComparison.Ordinal);
            string url = "";
            if (hrefPos >= 0)
            {
                var hrefEnd = html.IndexOf('"', hrefPos + 6);
                if (hrefEnd > hrefPos)
                    url = System.Net.WebUtility.HtmlDecode(html[(hrefPos + 6)..hrefEnd]);
            }

            var titleEnd = html.IndexOf("</a>", linkStart, StringComparison.Ordinal);
            var titleStart = html.LastIndexOf('>', titleEnd - 1, Math.Min(titleEnd - linkStart, 500));
            var title = titleStart >= 0 && titleEnd > titleStart
                ? StripHtml(html[(titleStart + 1)..titleEnd])
                : "Untitled";

            var snippetMarker = html.IndexOf("result__snippet", titleEnd, StringComparison.Ordinal);
            var snippet = "";
            if (snippetMarker >= 0)
            {
                var sStart = html.IndexOf('>', snippetMarker);
                var sEnd = html.IndexOf('<', sStart + 1);
                if (sStart >= 0 && sEnd > sStart)
                    snippet = StripHtml(html[(sStart + 1)..sEnd]).Trim();
            }

            if (!string.IsNullOrWhiteSpace(title))
                results.Add((title.Trim(), snippet, url));

            searchIndex = titleEnd > 0 ? titleEnd + 1 : linkStart + 1;
        }

        return results;
    }

    private static string StripHtml(string input) =>
        System.Text.RegularExpressions.Regex.Replace(
            System.Net.WebUtility.HtmlDecode(input), "<[^>]+>", "");
}

/// <summary>Simple in-memory notepad for the agent to store research findings.</summary>
sealed class Notepad
{
    private readonly Dictionary<string, string> _notes = new();

    public void Save(string title, string content) => _notes[title] = content;

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        var sb = new StringBuilder();
        foreach (var (title, content) in _notes)
        {
            sb.AppendLine($"## {title}");
            sb.AppendLine(content);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

